CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(role), UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role); $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.assign_website_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF lower(NEW.email) = 'lakshman.macrow@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.assign_website_owner() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER assign_website_owner AFTER INSERT OR UPDATE OF email_confirmed_at, email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_website_owner();
CREATE TABLE public.website_content (key text PRIMARY KEY, published jsonb NOT NULL DEFAULT '{}'::jsonb, draft jsonb NOT NULL DEFAULT '{}'::jsonb, version integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.website_content TO anon;
GRANT SELECT, INSERT, UPDATE ON public.website_content TO authenticated;
GRANT ALL ON public.website_content TO service_role;
ALTER TABLE public.website_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public content read" ON public.website_content FOR SELECT TO anon USING (true);
CREATE POLICY "Owner content access" ON public.website_content FOR ALL TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
REVOKE SELECT ON public.website_content FROM anon;
GRANT SELECT (key, published) ON public.website_content TO anon;
CREATE TABLE public.consultation_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), name text NOT NULL, phone text NOT NULL, stage text NOT NULL, program text NOT NULL, region text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'new', notes text NOT NULL DEFAULT '', CHECK (status IN ('new', 'contacted', 'enrolled', 'closed')));
GRANT SELECT, UPDATE ON public.consultation_submissions TO authenticated;
GRANT ALL ON public.consultation_submissions TO service_role;
ALTER TABLE public.consultation_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner enquiry read" ON public.consultation_submissions FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Owner enquiry update" ON public.consultation_submissions FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
ALTER TABLE public.diwali_leads ADD COLUMN status text NOT NULL DEFAULT 'new', ADD COLUMN notes text NOT NULL DEFAULT '';
ALTER TABLE public.diwali_leads ADD CONSTRAINT diwali_leads_status CHECK (status IN ('new', 'contacted', 'enrolled', 'closed'));
GRANT SELECT, UPDATE ON public.diwali_leads TO authenticated;
CREATE POLICY "Owner offer lead read" ON public.diwali_leads FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Owner offer lead update" ON public.diwali_leads FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.content_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), user_id uuid NOT NULL, content jsonb NOT NULL, action text NOT NULL);
GRANT SELECT, INSERT ON public.content_history TO authenticated;
GRANT ALL ON public.content_history TO service_role;
ALTER TABLE public.content_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner history read" ON public.content_history FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Owner history insert" ON public.content_history FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND public.has_role(auth.uid(), 'admin'));
CREATE FUNCTION public.save_website_content(payload jsonb, publish_now boolean, expected_version integer) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE new_version integer; BEGIN IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.website_content(key) VALUES ('site') ON CONFLICT DO NOTHING; UPDATE public.website_content SET draft = payload, published = CASE WHEN publish_now THEN payload ELSE published END, version = version + 1, updated_at = now() WHERE key = 'site' AND version = expected_version RETURNING version INTO new_version; IF new_version IS NULL THEN RAISE EXCEPTION 'Content changed. Reload before saving.'; END IF; INSERT INTO public.content_history(user_id, content, action) VALUES(auth.uid(), payload, CASE WHEN publish_now THEN 'published' ELSE 'draft saved' END); RETURN new_version; END; $$;
REVOKE ALL ON FUNCTION public.save_website_content(jsonb, boolean, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_website_content(jsonb, boolean, integer) TO authenticated;